int remount_shmem(struct super_block *sb, int *flags, char *data) {
    struct shmem_config config = {0};
    int result = -EINVAL;

    if (!sb || !flags || !data) {
        return -EINVAL;
    }

    if (parse_shmem_options(data, &config) != 0) {
        return -EINVAL;
    }

    if (config.max_blocks <= 0 || config.max_inodes <= 0) {
        return -EINVAL;
    }

    spin_lock(&sb->s_lock);

    if (sb->s_bdev && sb->s_bdev->bd_super) {
        if (sb->s_bdev->bd_super->s_blocks_used > config.max_blocks ||
            sb->s_bdev->bd_super->s_inodes_used > config.max_inodes) {
            spin_unlock(&sb->s_lock);
            return -ENOSPC;
        }
    }

    sb->s_max_blocks = config.max_blocks;
    sb->s_max_inodes = config.max_inodes;

    if (config.flags & SHMEM_FLAG_NOINODES) {
        sb->s_flags |= SB_NOINODES;
    } else {
        sb->s_flags &= ~SB_NOINODES;
    }

    if (config.flags & SHMEM_FLAG_NODIRTY) {
        sb->s_flags |= SB_NODIRTY;
    } else {
        sb->s_flags &= ~SB_NODIRTY;
    }

    spin_unlock(&sb->s_lock);

    return 0;
}
